    step: 1,
    description: "Word stagger",
    hiddenFromList: false,
  },
  hold: {
    type: "number",
    default: 36,
    min: 0,
    max: 90,
    step: 1,
    description: "Final hold (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Syne",
    description: "Font",
  },
