  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","fontWeight","stagger","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  fontWeight: 500,
  stagger: 3,
  hold: 36,
  fontFamily: "Syne",
  scale: 1,
  delay: 0,
  speed: 1,
};

type CueWordElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CueWordBase>;

const CueWordInner = forwardRef<
  HTMLDivElement,
  CueWordElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CueWord>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CueWordBase
          {...(componentProps as unknown as ComponentProps<typeof CueWordBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CueWord = Interactive.withSchema({
  Component: CueWordInner,
  componentName: "<CueWord>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
